68	// Options configures a Log opened with Open.
69	type Options struct {
70		// SegmentBytes is the capacity of one segment file in bytes. Once a
71		// non-empty segment would exceed it, the log rolls to a new segment.
72		// A single batch or group larger than the capacity occupies its own
73		// segment. Must be positive.
74		SegmentBytes int
75		// Sync makes Commit and CommitGroup fsync the segment file before
76		// returning, so a returned commit is durable.
77		Sync bool
78	}
