80	// Batch is a group of records identified by a single sequence number.
81	// A Batch returned by Append is staged; after Commit or CommitGroup it
82	// is readable. A batch staged with AppendIdempotent additionally
83	// carries the caller-chosen idempotency key, returned by ID; anonymous
84	// batches return "" from ID.
85	type Batch struct {
86		seq     uint64
87		id      string
88		records [][]byte
89		owner   *Log
90	}
91	
92	// Seq returns the sequence number reserved for the batch.
93	func (b Batch) Seq() uint64 { return b.seq }
94	
95	// ID returns the batch's idempotency key as given to
96	// AppendIdempotent, or "" for an anonymous batch staged with Append.
97	func (b Batch) ID() string { return b.id }
98	
99	// Records returns a copy of the batch's records.
100	func (b Batch) Records() [][]byte { return copyRecords(b.records) }
