102	// Segment describes one segment file by the committed sequences it holds.
103	type Segment struct {
104		FirstSeq uint64
105		LastSeq  uint64
106	}
107	
108	// entryRef locates one committed batch body inside a segment file. The
109	// persistent index sidecar stores the same locations; its loss or
110	// invalidation is always safe because Open rebuilds it from the
111	// segments. gen is the publication generation of the commit that
112	// published the batch; every member of a group commit shares one gen,
113	// which lets a streaming replay snapshot see the whole group or none of
114	// it.
115	type entryRef struct {
116		seg    int // segment file number
117		off    int // offset of the batch body within the segment
118		length int // length of the batch body
119		gen    uint64
120		id     string // idempotency key, "" for an anonymous batch
121		keyed  bool   // body uses key framing (BCLI, or any BCLK member)
122	}
123	
124	// Log is an append-only batch-commit log stored in a directory of
125	// segment files. It is safe for concurrent use, but the writer side is
126	// expected to be a single goroutine (see README Limits).
127	//
128	// The read and write paths are decoupled: writers take mu exclusively,
129	// while readers hold it only for the brief index and staged-state
130	// lookups. Segment file reads, decoding and user callbacks happen
131	// outside the lock, so a slow reader or a long replay never blocks a
132	// committing writer.
133	type Log struct {
134		dir  string
135		opts Options
136	
137		// mu guards the mutable index and write state below. Readers never
138		// hold it across file I/O, decoding or callbacks.
139		mu         sync.RWMutex
140		file       *os.File // current segment, nil until first write
141		fileSize   int
142		idxFile    *os.File // index sidecar, opened for append
143		idxSize    int
144		segIndex   int // index of the current segment file, 0 = none yet
145		curBatches int // committed batches in the current segment
146		nextSeq    uint64
147		staged     map[uint64][][]byte
148		stagedID   map[uint64]string // idempotency key of staged keyed batches
149		ids        map[string]uint64 // key -> seq of staged or committed keyed batch
150		index      map[uint64]entryRef
151		segs       []Segment // segments holding at least one committed batch
152		gen        uint64    // publication generation of the last commit
153		closed     bool
154	}
155	
156	// Open opens the log in dir, creating the directory if needed. The
157	// committed set is taken from the persistent index sidecar when it can
158	// be adopted incrementally; if the sidecar is missing, truncated, from
159	// another version, checksum-bad or contradictory to the segment files,
160	// Open transparently rebuilds it by scanning the segments once. Either
161	// path yields identical reads, replays, segment listings and errors.
162	//
163	// A half-written tail of the last segment — the remnant of a crash
164	// mid-write — is replaced by a durable hole marker without error and
165	// its reserved sequences stay permanent holes across reopens; any other
166	// inconsistency is ErrCorruptSegment.
167	func Open(dir string, opts Options) (*Log, error) {
168		if opts.SegmentBytes <= 0 {
169			return nil, ErrInvalidOptions
170		}
171		if err := os.MkdirAll(dir, 0o755); err != nil {
172			return nil, err
173		}
174		entries, err := os.ReadDir(dir)
175		if err != nil {
176			return nil, err
177		}
178		var indices []int
179		for _, e := range entries {
180			if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
181				continue
182			}
183			n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
184			if err != nil {
185				continue
186			}
187			indices = append(indices, n)
188		}
189		sort.Ints(indices)
190	
191		l := &Log{
192			dir:      dir,
193			opts:     opts,
194			nextSeq:  1,
195			staged:   make(map[uint64][][]byte),
196			stagedID: make(map[uint64]string),
197			ids:      make(map[string]uint64),
198			index:    make(map[uint64]entryRef),
199		}
200	
201		// Segment sizes are all the segment metadata adoption needs; the
202		// contents are touched only by the cheap CRC pass, never decoded
203		// entry by entry.
204		sizes := make(map[int]int, len(indices))
205		for _, n := range indices {
206			st, err := os.Stat(l.segmentPath(n))
207			if err != nil {
208				return nil, err
209			}
210			sizes[n] = int(st.Size())
211		}
212	
213		snapshot, ok := l.adoptIndex(indices, sizes)
214		if !ok {
215			snapshot, err = l.rebuildFromSegments(indices)
216			if err != nil {
217				return nil, err
218			}
219		}
220		sortIndexSnapshot(&snapshot)
221		if err := l.installSnapshot(snapshot, indices); err != nil {
222			return nil, err
223		}
224	
225		if len(indices) > 0 {
226			l.segIndex = indices[len(indices)-1]
227			if err := l.openCurrent(); err != nil {
228				return nil, err
229			}
230		}
231		if err := l.openIndex(); err != nil {
232			return nil, err
233		}
234		return l, nil
235	}
236	
237	// installSnapshot populates the in-memory index, segment listing, staged
238	// holes, key map and next-sequence counter from an adopted or rebuilt
239	// snapshot. Both open paths funnel through here so their observable
240	// state is identical. Entries must be ordered by (segment, disk offset);
241	// each entry (a single commit or one group) gets one publication
242	// generation. A key claimed by two complete entries, or a complete
243	// entry whose member framing disagrees with the index, is corruption.
244	func (l *Log) installSnapshot(p parsedIndex, indices []int) error {
245		for i := range p.entries {
246			e := &p.entries[i]
247			l.gen++
248			for _, m := range e.members {
249				l.index[m.seq] = entryRef{
250					seg: e.seg, off: m.off, length: m.length, gen: l.gen,
251					id: m.id, keyed: e.keyed,
252				}
253				if m.id != "" {
254					if _, dup := l.ids[m.id]; dup {
255						return ErrCorruptSegment
256					}
257					l.ids[m.id] = m.seq
258				}
259				if m.seq >= l.nextSeq {
260					l.nextSeq = m.seq + 1
261				}
262			}
263		}
264		// Segment listing: one entry per physical segment that holds at
265		// least one committed batch.
266		segSeen := make(map[int]int)
267		for i := range p.entries {
268			e := &p.entries[i]
269			var first, last uint64
270			for j, m := range e.members {
271				if j == 0 {
272					first, last = m.seq, m.seq
273				}
274				if m.seq < first {
275					first = m.seq
276				}
277				if m.seq > last {
278					last = m.seq
279				}
280			}
281			if idx, known := segSeen[e.seg]; known {
282				if first < l.segs[idx].FirstSeq {
283					l.segs[idx].FirstSeq = first
284				}
285				if last > l.segs[idx].LastSeq {
286					l.segs[idx].LastSeq = last
287				}
288			} else {
289				segSeen[e.seg] = len(l.segs)
290				l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
291			}
292		}
293		// Holes reserve sequences permanently: they read as staged (never
294		// committed) and are never reused, across any number of reopens.
295		for i := range p.holes {
296			for _, seq := range p.holes[i].seqs {
297				if seq == 0 {
298					continue
299				}
300				if _, committed := l.index[seq]; !committed {
301					l.staged[seq] = nil
302				}
303				if seq >= l.nextSeq {
304					l.nextSeq = seq + 1
305				}
306			}
307		}
308		if len(indices) > 0 {
309			last := indices[len(indices)-1]
310			l.curBatches = 0
311			for i := range p.entries {
312				if p.entries[i].seg == last {
313					l.curBatches += len(p.entries[i].members)
314				}
315			}
316		}
317		return nil
318	}
319	
320	// sortIndexSnapshot orders a snapshot's records by (segment, offset),
321	// the canonical on-disk and publication order.
322	func sortIndexSnapshot(p *parsedIndex) {
323		sort.SliceStable(p.entries, func(i, j int) bool {
324			if p.entries[i].seg != p.entries[j].seg {
325				return p.entries[i].seg < p.entries[j].seg
326			}
327			return p.entries[i].off < p.entries[j].off
328		})
329		sort.SliceStable(p.holes, func(i, j int) bool {
330			if p.holes[i].seg != p.holes[j].seg {
331				return p.holes[i].seg < p.holes[j].seg
332			}
333			return p.holes[i].off < p.holes[j].off
334		})
335	}
