337	// adoptIndex is the incremental open path. It verifies the sidecar
338	// against the segment files without decoding record bodies: its records
339	// must tile a prefix of the segment files from offset zero, every
340	// on-disk CRC must match, and member locations must agree with the entry
341	// headers. Any framing defect, a truncated final record, a version
342	// mismatch or a contradiction makes it return ok=false and Open rebuilds
343	// from the segments instead.
344	//
345	// The segments may legitimately extend past a verified index — the
346	// crash window between the segment sync and the index record sync. That
347	// suffix (extra bytes of the last covered segment, plus any whole later
348	// segment) is parsed incrementally: complete entries get indexed, a
349	// torn tail of the last segment becomes a hole marker, so adoption
350	// still costs one small decode rather than a full scan.
351	func (l *Log) adoptIndex(indices []int, sizes map[int]int) (parsedIndex, bool) {
352		if len(indices) == 0 {
353			// No segments: nothing to index; openIndex creates the sidecar
354			// lazily with its header when the first commit lands.
355			return parsedIndex{}, true
356		}
357		data, err := l.readIndexBytes()
358		if err != nil {
359			return parsedIndex{}, false
360		}
361		p, tailLen, err := readIndexFile(data)
362		if err != nil || tailLen > 0 {
363			// Missing/truncated/foreign sidecar: the rebuild path owns
364			// these cases.
365			return parsedIndex{}, false
366		}
367		if len(p.entries) == 0 && len(p.holes) == 0 {
368			// A recordless sidecar is valid only when every segment is
369			// empty; otherwise the sidecar is simply behind and the
370			// rebuild path catches up.
371			for _, n := range indices {
372				if sizes[n] != 0 {
373					return parsedIndex{}, false
374				}
375			}
376			return p, true
377		}
378		covered, covEnd, ok := l.verifySidecar(p, indices, sizes)
379		if !ok {
380			return parsedIndex{}, false
381		}
382	
383		// Everything at or after covered is unverified suffix: the unindexed
384		// tail bytes of segment covered, then every whole later segment.
385		pos := 0
386		for pos < len(indices) && indices[pos] < covered {
387			pos++
388		}
389		var extra []diskRecord
390		for si := pos; si < len(indices); si++ {
391			n := indices[si]
392			raw, err := os.ReadFile(l.segmentPath(n))
393			if err != nil {
394				return parsedIndex{}, false
395			}
396			base := 0
397			if n == covered {
398				if covEnd > len(raw) {
399					return parsedIndex{}, false
400				}
401				base = covEnd
402			}
403			batches, markers, tail, perr := parseSegment(raw[base:])
404			if perr != nil {
405				// Tampering in the suffix surfaces through the rebuild path
406				// with the identical ErrCorruptSegment.
407				return parsedIndex{}, false
408			}
409			if tail != nil && si != len(indices)-1 {
410				return parsedIndex{}, false
411			}
412			for k := 0; k < len(batches); {
413				diskOff := batches[k].diskOff + base
414				j := k + 1
415				for j < len(batches) && batches[j].diskOff+base == diskOff {
416					j++
417				}
418				e := indexEntry{
419					seg:     n,
420					off:     diskOff,
421					length:  batches[k].diskLen,
422					diskCRC: batches[k].diskCRC,
423					keyed:   batches[k].keyed,
424					members: make([]indexMember, 0, j-k),
425				}
426				for _, pb := range batches[k:j] {
427					e.members = append(e.members, indexMember{
428						seq: pb.seq, id: pb.id, off: pb.off + base, length: pb.length,
429					})
430				}
431				p.entries = append(p.entries, e)
432				extra = append(extra, diskRecord{seg: n, off: diskOff, enc: encodeEntryRecord(e)})
433				k = j
434			}
435			for _, h := range markers {
436				ih := indexHole{
437					seg: n, off: h.off + base, length: h.length, diskCRC: h.crc,
438					seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
439				}
440				p.holes = append(p.holes, ih)
441				extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
442			}
443			if tail != nil {
444				keep := make([]uint64, 0, len(tail.seqs))
445				for _, seq := range tail.seqs {
446					if seq > 0 {
447						keep = append(keep, seq)
448					}
449				}
450				if err := l.rewriteTail(n, base+tail.off, keep); err != nil {
451					return parsedIndex{}, false
452				}
453				if len(keep) > 0 {
454					marker := encodeHoles(keep)
455					crc := binary.LittleEndian.Uint32(marker[len(marker)-4:])
456					ih := indexHole{
457						seg: n, off: base + tail.off, length: len(marker), diskCRC: crc,
458						seqs: append(make([]uint64, 0, len(keep)), keep...),
459					}
460					p.holes = append(p.holes, ih)
461					extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
462				}
463			}
464		}
465	
466		// Persist the incrementally recovered records so later opens adopt
467		// them too. A crash during this append leaves a torn final index
468		// record, and the next open simply rebuilds.
469		if len(extra) > 0 {
470			if err := l.appendAdoptedSuffix(extra); err != nil {
471				return parsedIndex{}, false
472			}
473		}
474		return p, true
475	}
476	
477	// appendAdoptedSuffix appends incrementally recovered records to the
478	// sidecar and fsyncs it. Failure means the caller rebuilds instead.
479	func (l *Log) appendAdoptedSuffix(recs []diskRecord) error {
480		sort.SliceStable(recs, func(i, j int) bool {
481			if recs[i].seg != recs[j].seg {
482				return recs[i].seg < recs[j].seg
483			}
484			return recs[i].off < recs[j].off
485		})
486		f, err := os.OpenFile(l.indexPath(), os.O_WRONLY|os.O_APPEND, 0o644)
487		if err != nil {
488			return err
489		}
490		defer f.Close()
491		for _, r := range recs {
492			if _, err := f.Write(r.enc); err != nil {
493				return err
494			}
495		}
496		return f.Sync()
497	}
498	
499	// sidecarRec is one physical record the index claims.
500	type sidecarRec struct {
501		seg    int
502		off    int
503		length int
504		crc    uint32
505		entry  *indexEntry
506		hole   *indexHole
507	}
508	
509	// verifySidecar checks an already-framed parse against the physical
510	// segments without decoding any record body. It returns the last segment
511	// the index covers and the offset immediately after its records there.
512	//
513	// The covered segments must be a prefix of the segment files in the
514	// directory; within each one records must be strictly ordered, start at
515	// offset zero and tile without gaps or overlap. Every covered segment
516	// except the last must end exactly at the file size (nothing
517	// unindexed); the last one may stop short, leaving a suffix for
518	// incremental parsing. Every stored disk CRC is recomputed, and entry
519	// headers (magic and group membership layout) are checked.
520	func (l *Log) verifySidecar(p parsedIndex, indices []int, sizes map[int]int) (coveredSeg int, coveredEnd int, ok bool) {
521		if len(indices) == 0 {
522			return 0, 0, false
523		}
524		recs := make([]sidecarRec, 0, len(p.entries)+len(p.holes))
525		for i := range p.entries {
526			e := &p.entries[i]
527			recs = append(recs, sidecarRec{seg: e.seg, off: e.off, length: e.length, crc: e.diskCRC, entry: e})
528		}
529		for i := range p.holes {
530			h := &p.holes[i]
531			recs = append(recs, sidecarRec{seg: h.seg, off: h.off, length: h.length, crc: h.diskCRC, hole: h})
532		}
533		sort.SliceStable(recs, func(i, j int) bool {
534			if recs[i].seg != recs[j].seg {
535				return recs[i].seg < recs[j].seg
536			}
537			return recs[i].off < recs[j].off
538		})
539	
540		known := make(map[int]bool, len(indices))
541		for _, n := range indices {
542			known[n] = true
543		}
544		covered := false
545		seenSeq := make(map[uint64]bool)
546		seenKey := make(map[string]bool)
547		var f *os.File
548		openSeg := -1
549		closeFile := func() {
550			if f != nil {
551				f.Close()
552				f = nil
553				openSeg = -1
554			}
555		}
556		defer closeFile()
557	
558		prevSeg, prevEnd := -1, 0
559		for i := range recs {
560			r := &recs[i]
561			if !known[r.seg] || r.off < 0 || r.length < 16 {
562				return 0, 0, false
563			}
564			if r.seg != prevSeg {
565				// A new covered segment: the previous one must be tiled to
566				// its EOF, and the covered segments must be a prefix with no
567				// unindexed segment file in between.
568				if prevSeg != -1 && prevEnd != sizes[prevSeg] {
569					return 0, 0, false
570				}
571				if covered {
572					next := 0
573					found := false
574					for _, n := range indices {
575						if n > prevSeg {
576							next, found = n, true
577							break
578						}
579					}
580					if !found || r.seg != next || r.off != 0 {
581						return 0, 0, false
582					}
583				} else {
584					if r.seg != indices[0] || r.off != 0 {
585						return 0, 0, false
586					}
587				}
588				covered = true
589				prevSeg = r.seg
590				prevEnd = 0
591				closeFile()
592				var err error
593				f, err = os.Open(l.segmentPath(r.seg))
594				if err != nil {
595					return 0, 0, false
596				}
597				openSeg = r.seg
598			}
599			if openSeg != r.seg || r.off != prevEnd || r.off+r.length > sizes[r.seg] {
600				return 0, 0, false
601			}
602			if !l.verifyDiskRecord(f, r, seenSeq, seenKey) {
603				return 0, 0, false
604			}
605			prevEnd = r.off + r.length
606		}
607		lastSeg := recs[len(recs)-1].seg
608		lastEnd := prevEnd
609	
610		// Every segment file before the last covered one must carry at
611		// least one index record (no unindexed segment in the middle).
612		refSegs := map[int]bool{}
613		for i := range recs {
614			refSegs[recs[i].seg] = true
615		}
616		for _, n := range indices {
617			if n < lastSeg && !refSegs[n] {
618				return 0, 0, false
619			}
620		}
621		return lastSeg, lastEnd, true
622	}
623	
624	// verifyDiskRecord checks one index claim against the segment without
625	// holding the entry in memory: a small header read, a streaming CRC over
626	// a fixed-size scratch buffer, and small reads of group-member sequences
627	// and key frames. It never decodes record bodies.
628	func (l *Log) verifyDiskRecord(f *os.File, r *sidecarRec, seenSeq map[uint64]bool, seenKey map[string]bool) bool {
629		var hdr [16]byte
630		if _, err := f.ReadAt(hdr[:12], int64(r.off)); err != nil {
631			return false
632		}
633		// Stream the entry's CRC-covered prefix through one reused buffer,
634		// then compare against the stored trailing checksum.
635		h := crc32.NewIEEE()
636		buf := make([]byte, 64*1024)
637		remaining := r.length - 4
638		at := int64(r.off)
639		for remaining > 0 {
640			n := len(buf)
641			if n > remaining {
642				n = remaining
643			}
644			if _, err := f.ReadAt(buf[:n], at); err != nil {
645				return false
646			}
647			h.Write(buf[:n])
648			remaining -= n
649			at += int64(n)
650		}
651		var crcBytes [4]byte
652		if _, err := f.ReadAt(crcBytes[:], at); err != nil {
653			return false
654		}
655		stored := binary.LittleEndian.Uint32(crcBytes[:])
656		if h.Sum32() != stored || stored != r.crc {
657			return false
658		}
659	
660		switch {
661		case r.entry != nil:
662			e := r.entry
663			switch {
664			case bytes.Equal(hdr[:4], segmentMagic):
665				if e.keyed || len(e.members) != 1 || e.members[0].id != "" {
666					return false
667				}
668				return len(e.members) == 1 &&
669					e.members[0].seq == binary.LittleEndian.Uint64(hdr[4:12]) &&
670					e.members[0].off == r.off+4 &&
671					e.members[0].length == r.length-8 &&
672					markSeen(e.members, seenSeq, nil)
673			case bytes.Equal(hdr[:4], keyedMagic):
674				if !e.keyed || len(e.members) != 1 {
675					return false
676				}
677				m := e.members[0]
678				if m.id == "" ||
679					m.seq != binary.LittleEndian.Uint64(hdr[4:12]) ||
680					m.off != r.off+4 || m.length != r.length-8 {
681					return false
682				}
683				if _, ok := verifyKeyOnDisk(f, int64(m.off+8), m.id); !ok {
684					return false
685				}
686				return markSeen(e.members, seenSeq, seenKey)
687			case bytes.Equal(hdr[:4], groupMagic):
688				if e.keyed {
689					return false
690				}
691				if uint32(len(e.members)) != binary.LittleEndian.Uint32(hdr[4:8]) {
692					return false
693				}
694				if !checkMemberLayout(r, e) {
695					return false
696				}
697				for _, m := range e.members {
698					if m.id != "" {
699						return false
700					}
701					var seqBytes [8]byte
702					if _, err := f.ReadAt(seqBytes[:], int64(m.off)); err != nil {
703						return false
704					}
705					if m.seq != binary.LittleEndian.Uint64(seqBytes[:]) {
706						return false
707					}
708				}
709				return markSeen(e.members, seenSeq, nil)
710			case bytes.Equal(hdr[:4], keyedGroup):
711				if !e.keyed {
712					return false
713				}
714				if uint32(len(e.members)) != binary.LittleEndian.Uint32(hdr[4:8]) {
715					return false
716				}
717				if !checkMemberLayout(r, e) {
718					return false
719				}
720				for _, m := range e.members {
721					if _, ok := verifyKeyOnDisk(f, int64(m.off+8), m.id); !ok {
722						return false
723					}
724					var seqBytes [8]byte
725					if _, err := f.ReadAt(seqBytes[:], int64(m.off)); err != nil {
726						return false
727					}
728					if m.seq != binary.LittleEndian.Uint64(seqBytes[:]) {
729						return false
730					}
731				}
732				return markSeen(e.members, seenSeq, seenKey)
733			default:
734				return false
735			}
736		case r.hole != nil:
737			h2 := r.hole
738			if !bytes.Equal(hdr[:4], holeMagic) ||
739				uint32(len(h2.seqs)) != binary.LittleEndian.Uint32(hdr[4:8]) ||
740				r.length != 4+4+8*len(h2.seqs)+4 {
741				return false
742			}
743			// The reserved sequences themselves must agree with the marker,
744			// not just their count.
745			seqBytes := make([]byte, 8*len(h2.seqs))
746			if len(seqBytes) > 0 {
747				if _, err := f.ReadAt(seqBytes, int64(r.off+8)); err != nil {
748					return false
749				}
750				for i, seq := range h2.seqs {
751					if seq == 0 || seenSeq[seq] ||
752						seq != binary.LittleEndian.Uint64(seqBytes[8*i:8*i+8]) {
753						return false
754					}
755				}
756			}
757			return true
758		default:
759			return false
760		}
761	}
