763	// checkMemberLayout verifies that a group entry's member bodies tile the
764	// entry's CRC-covered payload with no gaps or overhang, starting right
765	// after the 8-byte group header.
766	func checkMemberLayout(r *sidecarRec, e *indexEntry) bool {
767		bodyStart := r.off + 8
768		for i, m := range e.members {
769			rel := m.off - r.off
770			if m.length <= 0 || rel < 8 || rel+m.length > r.length-4 {
771				return false
772			}
773			if i == 0 {
774				if m.off != bodyStart {
775					return false
776				}
777			} else {
778				prev := e.members[i-1]
779				if m.off != prev.off+prev.length {
780					return false
781				}
782			}
783		}
784		return e.members[len(e.members)-1].off+e.members[len(e.members)-1].length == r.off+r.length-4
785	}
