149	func TestScanInOrderAndAtomic(t *testing.T) {
150		l := open(t, t.TempDir(), log.Options{SegmentBytes: 1 << 20})
151	
152		// Stage three batches, commit the middle one last.
153		b1, _ := l.Append([][]byte{[]byte("r1")})
154		b2, _ := l.Append([][]byte{[]byte("r2a"), []byte("r2b")})
155		b3, _ := l.Append([][]byte{[]byte("r3")})
156		for _, b := range []log.Batch{b1, b3, b2} {
157			if _, err := l.Commit(b); err != nil {
158				t.Fatalf("Commit: %v", err)
159			}
160		}
161		if _, err := l.Append([][]byte{[]byte("staged")}); err != nil {
162			t.Fatalf("Append: %v", err)
163		}
164	
165		var seqs []uint64
166		var recs [][]string
167		err := l.Scan(1, func(b log.Batch) error {
168			seqs = append(seqs, b.Seq())
169			var rs []string
170			for _, r := range b.Records() {
171				rs = append(rs, string(r))
172			}
173			recs = append(recs, rs)
174			return nil
175		})
176		if err != nil {
177			t.Fatalf("Scan: %v", err)
178		}
179		if !reflect.DeepEqual(seqs, []uint64{1, 2, 3}) {
180			t.Fatalf("scan seqs = %v, want [1 2 3]", seqs)
181		}
182		want := [][]string{{"r1"}, {"r2a", "r2b"}, {"r3"}}
183		if !reflect.DeepEqual(recs, want) {
184			t.Fatalf("scan records = %v, want %v", recs, want)
185		}
186	
187		// From filters, and a callback error stops the replay.
188		count := 0
189		boom := errors.New("boom")
190		err = l.Scan(2, func(b log.Batch) error {
191			count++
192			return boom
193		})
194		if !errors.Is(err, boom) || count != 1 {
195			t.Fatalf("Scan error propagation: err=%v count=%d", err, count)
196		}
197	}
