521		l := open(t, dir, opts)
522		commit(t, l, []byte("one"))
523		commit(t, l, []byte("two"))
524		l.Close()
525	
526		l = open(t, dir, opts)
527		commit(t, l, []byte("three"))
528		segs := l.Segments()
529		if len(segs) != 1 || segs[0].FirstSeq != 1 || segs[0].LastSeq != 3 {
530			t.Fatalf("Segments = %+v, want one segment [1,3]", segs)
531		}
532	}
