	// And again after committing past the hole.
	l = open(t, dir, opts)
	if _, err := l.Read(2); !errors.Is(err, log.ErrNotCommitted) {
		t.Fatalf("after third open Read(2) err = %v, want ErrNotCommitted", err)
	}
