	data, err := os.ReadFile(l.truncMarkerPath())
	if err != nil {
		if os.IsNotExist(err) {
			return truncation{}, false, nil
		}
		return truncation{}, false, err
	}
	t, ok := parseTruncation(data)
	if !ok {
		return truncation{}, false, ErrCorruptSegment
	}
	return t, true, nil
}

// persistTruncation commits the marker durably: synced temp file, atomic
// rename, directory sync. Any failure leaves the previous marker (or its
// absence) intact.
func (l *Log) persistTruncation(t truncation) error {
	buf := encodeTruncation(t.through, t.nextSeq, t.deletedSegs)
	tmp := l.truncMarkerPath() + ".tmp"
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write(buf); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := syncFile(f); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, l.truncMarkerPath()); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := syncDir(l.dir); err != nil {
		return err
	}
	return nil
}

// DeleteThrough reclaims the oldest complete segments: every whole
// segment forming a prefix of the on-disk segment order whose last
// committed batch sequence is <= seq is deleted, and the number of
// segment files removed is returned. Nothing is rewritten: a batch, a
// group and a hole marker always stay wholly inside one segment, so a
// segment straddling seq (seq lands in its middle) is retained whole and
// one fewer segment may be removed.
//
// DeleteThrough(0) changes nothing and returns 0. Otherwise seq must
// name a committed sequence at or below the committed high-water mark:
// a never-reserved, merely staged, or out-of-range sequence, or one that
// would leave a reserved-but-uncommitted sequence inside the discarded
// prefix, returns ErrInvalidRetention and deletes nothing.
//
// The truncation point is persisted before any segment file is removed,
// so Read and Scan keep distinguishing reclaimed sequences
// (ErrTruncated) from unknown ones after a reopen and after index.idx is
// rebuilt. Ids used by removed batches are released and may be claimed by
// later AppendIdempotent calls. A persistence or sync failure returns
// ErrRetentionFailed with the old state fully intact; a crash during the
// deletion is reconciled on the next Open into either the complete old
// or the complete new state.
func (l *Log) DeleteThrough(seq uint64) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return 0, errClosed
	}
	if seq == 0 {
		return 0, nil
	}
	// Validation: seq must be a committed sequence at or below the
	// committed high-water mark. A staged (or permanently-holed)
	// reservation below it stays inside the retained window, so it is
	// not an error — only a reservation inside the discarded prefix is.
	ref, committed := l.index[seq]
	if !committed {
		return 0, ErrInvalidRetention
	}
	if len(l.segs) == 0 {
		return 0, ErrInvalidRetention
	}
	high := l.segs[len(l.segs)-1].LastSeq
	if seq > high {
		return 0, ErrInvalidRetention
	}

	// Count the deletable prefix: whole segments whose LastSeq <= seq.
	drop := 0
	for i := range l.segs {
		if l.segs[i].LastSeq <= seq {
			drop = i + 1
		} else {
			break
		}
	}
	if drop == 0 {
		// seq is committed but its own segment starts above seq — this is
		// only possible for corruption, but refuse rather than delete.
		return 0, ErrInvalidRetention
	}
	dropSegs := make([]int, drop)
	for i := 0; i < drop; i++ {
		dropSegs[i] = refSegNumber(l, i)
	}
	// A hole marker in a discarded segment could reserve a sequence
	// greater than seq (e.g. a torn tail in an earlier segment). Those
	// reservations must survive as permanent holes, so refuse rather than
	// silently forgetting them: nothing is deleted.
	if maxHoleSeq(l, dropSegs) > seq {
		return 0, ErrInvalidRetention
	}

	// Commit the durable intent before touching any segment.
	newTrunc := truncation{
		through:     seq,
		nextSeq:     l.nextSeq,
		deletedSegs: append(append([]int(nil), l.trunc.deletedSegs...), dropSegs...),
		hasMarker:   true,
	}
	if err := l.persistTruncation(newTrunc); err != nil {
		return 0, fmt.Errorf("%w: %v", ErrRetentionFailed, err)
	}

	// Remove the obsolete segments. The marker already authorises the
	// removal, so a failure (or a crash) here is finished on reopen.
	for _, n := range dropSegs {
		if err := os.Remove(l.segmentPath(n)); err != nil && !os.IsNotExist(err) {
			// The durable state is the new one; reads stay valid for every
			// surviving sequence, and reopen retries the removals. Surface
			// it as ErrRetentionFailed without pretending the truncation
			// rolled back.
			return 0, fmt.Errorf("%w: %v", ErrRetentionFailed, err)
		}
	}
	if err := syncDir(l.dir); err != nil {
		return 0, fmt.Errorf("%w: %v", ErrRetentionFailed, err)
	}

	if err := l.applyTruncationLocked(seq, dropSegs); err != nil {
		return 0, fmt.Errorf("%w: %v", ErrRetentionFailed, err)
	}
	l.trunc = newTrunc
	return drop, nil
}

// refSegNumber maps a position in l.segs to its physical segment number.
// The in-memory listing keeps no file number; the index entries (and
// holes) name physical segments, and segs is ordered with them.
func refSegNumber(l *Log, segPos int) int {
	want := l.segs[segPos]
	// Recover physical numbers actually present by scanning index refs;
	// the smallest segment number whose listing matches is this entry.
	nums := make(map[int]struct{})
	for _, r := range l.index {
		nums[r.seg] = struct{}{}
	}
	for _, h := range l.holeSegsSnapshot() {
		nums[h] = struct{}{}
	}
	var ordered []int
	for n := range nums {
		ordered = append(ordered, n)
	}
	sortInts(ordered)
	// segs is indexed in physical order; pick the segPos-th number that
	// carries committed batches within this segment's span.
	idx := -1
	for _, n := range ordered {
		var first, last uint64
		any := false
		for seq, r := range l.index {
			if r.seg != n {
				continue
			}
			if !any || seq < first {
				first = seq
			}
			if !any || seq > last {
				last = seq
			}
			any = true
		}
		if any && first == want.FirstSeq && last == want.LastSeq {
			idx++
			if idx == segPos {
				return n
			}
		}
	}
	// Fallback (should be unreachable): the segPos-th physical number.
	return ordered[segPos]
}

// applyTruncationLocked mutates in-memory state after the deleted prefix
// has been removed from disk and committed by the marker: drop index
// entries, ids and the segment listing for the removed segments, refresh
// the truncation watermark, and rewrite the sidecar as a snapshot of the
// surviving data.
func (l *Log) applyTruncationLocked(through uint64, dropSegs []int) error {
	dropped := make(map[int]bool, len(dropSegs))
	for _, n := range dropSegs {
		dropped[n] = true
	}
	// Drop index refs and release idempotent keys of removed batches.
	for seq, r := range l.index {
		if !dropped[r.seg] {
			continue
		}
		if r.id != "" {
			delete(l.ids, r.id)
		}
		delete(l.index, seq)
	}
	// Hole markers live only in removed or surviving segments; drop the
	// in-memory records for removed ones (validation guarantees they
	// reserved no sequence above through).
	l.dropHolesLocked(dropped)

	keep := len(l.segs) - len(dropSegs)
	if keep < 0 {
		keep = 0
	}
	l.segs = l.segs[len(l.segs)-keep:]
	if keep == 0 {
		// Every committed segment is gone. The live file handle and its
		// physical file were just removed; the next write rolls a fresh
		// segment with a new number past anything ever used.
		if l.file != nil {
			l.file.Close()
			l.file = nil
		}
		l.fileSize = 0
		l.curBatches = 0
		l.segIndex = maxSegNumber(l.trunc.deletedSegs, dropSegs)
	} else {
		// If the first surviving segment was also the open current one,
		// nothing changes for the writer; deleted prefix segments are
		// always older. Re-point state at the first survivor only when the
		// current segment was itself removed (the all-deleted case above).
		// curBatches already counts the surviving current segment.
	}
	l.truncThrough = through

	// Persist a fresh index snapshot of the surviving segments so the
	// next open adopts rather than rebuilds. Adoption tolerates the
	// missing prefix because the marker lists it as deleted.
	if err := l.snapshotSurvivorsLocked(); err != nil {
		// Not fatal to the committed truncation (the marker is durable):
		// the next open rebuilds from the surviving segments. But surface
		// the failure honestly.
		return err
	}
	return nil
}

// maxSegNumber returns the largest segment number across the two
// (possibly overlapping) lists, or 0 when both are empty.
func maxSegNumber(a, b []int) int {
	m := 0
	for _, n := range a {
		if n > m {
			m = n
		}
	}
	for _, n := range b {
		if n > m {
			m = n
		}
	}
	return m
}

// reconcileTruncation finishes or confirms a committed deletion after
// Open has parsed whatever segments exist. It deletes any segment the
// marker records as removed that is still present, then lets Open rebuild
// the index from the survivors when the sidecar no longer matches. It
// returns the list of segment numbers physically present afterwards.
func (l *Log) reconcileTruncation(t truncation, present []int) ([]int, bool) {
	deleted := make(map[int]bool, len(t.deletedSegs))
	for _, n := range t.deletedSegs {
		deleted[n] = true
	}
	kept := present[:0]
	changed := false
	for _, n := range present {
		if deleted[n] {
			if err := os.Remove(l.segmentPath(n)); err != nil && !os.IsNotExist(err) {
				return present, false
			}
			changed = true
			continue
		}
		kept = append(kept, n)
	}
	if changed {
		_ = syncDir(l.dir)
	}
	return kept, true
}

