213	// committedSegNumbers returns the physical segment numbers that hold at
214	// least one committed batch, in ascending order. The listing l.segs is
215	// in one-to-one order with this slice.
216	func (l *Log) committedSegNumbers() []int {
217		set := make(map[int]struct{})
218		for _, r := range l.index {
219			set[r.seg] = struct{}{}
220		}
221		out := make([]int, 0, len(set))
222		for n := range set {
223			out = append(out, n)
224		}
225		sort.Ints(out)
226		return out
227	}
228	
229	// DeleteThrough reclaims the oldest complete segments: every whole
230	// segment file up to and including the segment of seq whose last
231	// committed batch sequence is <= seq is deleted, and the number of
232	// segment files removed is returned. Nothing is rewritten — a batch, a
233	// group and a hole marker each stay wholly inside one segment, so a
234	// segment straddling seq is retained whole and one fewer segment may be
235	// removed.
236	//
237	// DeleteThrough(0) changes nothing and returns 0. Otherwise seq must name
238	// a committed sequence at or below the committed high-water mark: a
239	// never-reserved, merely staged, or out-of-range sequence returns
240	// ErrInvalidRetention and deletes nothing. A prefix segment whose hole
241	// marker reserves a sequence above seq is refused for the same reason,
242	// since that permanent hole must not be silently forgotten.
243	//
244	// The truncation point is persisted before any segment file is removed,
245	// so Read keeps distinguishing reclaimed sequences (ErrTruncated) from
